```javascript
/* ═══════════════════════════════════════════════════════════════════
   Ledger client. State lives here, truth lives on disk.
═══════════════════════════════════════════════════════════════════ */
const $ = (id) => document.getElementById(id);
const els = {
  sessions: $('sessions'), search: $('search'), filterCount: $('filterCount'), sortbar: $('sortbar'),
  thread: $('thread'), input: $('input'), send: $('send'), title: $('titleInput'),
  headMeta: $('headMeta'), status: $('status'), charCount: $('charCount'),
  footDir: $('footDir'), footStats: $('footStats'), peek: $('peek'), peekPath: $('peekPath'),
  peekJson: $('peekJson'), peekStats: $('peekStats'), toasts: $('toasts'),
};

const state = {
  sessions: [], current: null, pending: false,   // pending = not yet written to disk
  sort: 'recent', query: '', busy: false,
  saveTimer: null, stats: { count: 0, bytes: 0, dir: './data/sessions', readable: '0 B' },
  file: null, fileBytes: 0, renderedFor: null, lastBytes: -1,
};

/* ── tiny helpers ───────────────────────────────────────────────── */
const uid = (p = 's') => `${p}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;
const esc = (s) => String(s).replace(/[&<>]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[ch]));
const human = (n) => (!n ? '0 B' : (() => { const u = ['B','KB','MB','GB'], i = Math.min(Math.floor(Math.log(n)/Math.log(1024)), 3); return `${(n/1024**i).toFixed(i ? 1 : 0)} ${u[i]}`; })());
const clock = (d = new Date()) => d.toTimeString().slice(0, 8);

function ago(iso) {
  if (!iso) return '—';
  const s = (Date.now() - new Date(iso).getTime()) / 1000;
  if (s < 45) return 'now';
  if (s < 90) return '1m';
  if (s < 3600) return `${Math.round(s / 60)}m`;
  if (s < 86400) return `${Math.round(s / 3600)}h`;
  if (s < 604800) return `${Math.round(s / 86400)}d`;
  return new Date(iso).toISOString().slice(0, 10);
}
const full = (iso) => (iso ? new Date(iso).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—');
const words = (s) => String(s).trim().split(/\s+/).filter(Boolean).length;

/* ── api ────────────────────────────────────────────────────────── */
async function api(path, opts = {}) {
  const res = await fetch(path, { headers: { 'Content-Type': 'application/json' }, ...opts });
  const text = await res.text();
  const data = text ? JSON.parse(text) : {};
  if (!res.ok) throw new Error(data.error || `${res.status} ${res.statusText}`);
  return data;
}

/* ── markdown-lite ──────────────────────────────────────────────── */
function inline(s) {
  return esc(s)
    .replace(/`([^`\n]+)`/g, '<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(])_([^_\n]+)_(?=[\s).,!?:;]|$)/g, '$1<em>$2</em>')
    .replace(/\n/g, '<br>');
}
function md(text) {
  const src = String(text ?? '');
  const re = /```([\w-]*)\n?([\s\S]*?)```/g;
  let out = '', last = 0, m;
  while ((m = re.exec(src))) {
    out += inline(src.slice(last, m.index));
    out += `<pre data-lang="${esc(m[1] || 'code')}"><code>${esc(m[2].replace(/\n$/, ''))}</code></pre>`;
    last = m.index + m[0].length;
  }
  return out + inline(src.slice(last));
}

/* ── toasts ─────────────────────────────────────────────────────── */
function toast({ title, body, kind = '', action, ms = 6500 }) {
  const t = document.createElement('div');
  t.className = `toast${kind ? ' toast--' + kind : ''}`;
  t.innerHTML = `<b>${esc(title)}</b><span>${esc(body || '')}</span>`;
  if (action) {
    const b = document.createElement('button');
    b.textContent = action.label;
    b.onclick = () => { action.run(); close(); };
    t.appendChild(b);
  }
  const close = () => { t.classList.add('out'); setTimeout(() => t.remove(), 260); };
  setTimeout(close, ms);
  els.toasts.appendChild(t);
}

/* ── status pill ────────────────────────────────────────────────── */
function setStatus(kind, label) {
  els.status.dataset.state = kind;
  els.status.querySelector('span').textContent = label;
}

/* ══ persistence ═════════════════════════════════════════════════ */
function touch(label = 'editing…') {
  if (!state.current) return;
  setStatus('saving', label);
  clearTimeout(state.saveTimer);
  state.saveTimer = setTimeout(() => saveNow(), 650);
}

async function saveNow() {
  const s = state.current;
  if (!s) return;
  clearTimeout(state.saveTimer);
  setStatus('saving', 'saving…');
  try {
    const payload = { id: s.id, title: s.title, createdAt: s.createdAt, messages: s.messages };
    if (state.pending) {
      const r = await api('/api/sessions', { method: 'POST', body: JSON.stringify(payload) });
      state.pending = false;
      state.current = r.session; state.file = r.file; state.fileBytes = r.bytes;
    } else {
      const r = await api(`/api/sessions/${s.id}`, { method: 'PUT', body: JSON.stringify(payload) });
      state.current = r.session; state.file = r.file; state.fileBytes = r.bytes;
    }
    localStorage.setItem('ledger.current', state.current.id);
    setStatus('saved', `saved ${clock()}`);
    await refreshList(false);
    renderHead(); renderPeek(true);
  } catch (err) {
    setStatus('error', 'save failed');
    toast({ title: 'Write failed', body: err.message, kind: 'danger', action: { label: 'Retry', run: saveNow }, ms: 12000 });
  }
}

async function refreshList(openSpinner = true) {
  const r = await api('/api/sessions');
  state.sessions = r.sessions; state.stats = r.stats;
  if (state.current) {
    const mine = state.sessions.find((x) => x.id === state.current.id);
    if (mine && (state.pending || mine.updatedAt > state.current.updatedAt)) {
      // server copy is newer than a stale local view
    }
    state.pending = !state.sessions.some((x) => x.id === state.current.id);
  }
  renderList();
  els.footDir.textContent = state.stats.dir;
  els.footStats.textContent = `${state.stats.count} session${state.stats.count === 1 ? '' : 's'} · ${state.stats.readable}`;
  if (openSpinner) return;
}

/* ══ session lifecycle ═══════════════════════════════════════════ */
const blank = () => ({ id: uid('s'), title: 'Untitled session', createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), messages: [] });

async function newChat({ focus = true } = {}) {
  if (state.pending && state.current && !state.current.messages.length) {
    state.current = blank(); render(); if (focus) els.input.focus(); return;
  }
  await saveNow().catch(() => {});
  state.current = blank(); state.pending = true; state.renderedFor = null;
  localStorage.setItem('ledger.current', state.current.id);
  setStatus('idle', 'not saved yet');
  render();
  if (focus) els.input.focus();
  document.body.classList.remove('rail-open');
}

async function openChat(id) {
  if (state.current && state.pending && state.current.messages.length) await saveNow().catch(() => {});
  if (state.current && state.current.id === id && !state.pending) { document.body.classList.remove('rail-open'); return; }
  try {
    const r = await api(`/api/sessions/${id}`);
    state.current = r.session; state.pending = false; state.file = r.file; state.fileBytes = r.bytes;
    state.renderedFor = null;
    localStorage.setItem('ledger.current', id);
    setStatus('saved', 'loaded');
    render();
  } catch (err) { toast({ title: 'Could not open', body: err.message, kind: 'danger' }); refreshList(); }
  document.body.classList.remove('rail-open');
}

async function removeChat(id) {
  const local = state.sessions.find((s) => s.id === id);
  const isCurrent = state.current && state.current.id === id;
  if (state.pending && isCurrent) { state.current = blank(); state.renderedFor = null; render(); return; }
  try {
    const r = await api(`/api/sessions/${id}`, { method: 'DELETE' });
    const copy = r.restored || local;
    const idx = state.sessions.findIndex((s) => s.id === id);
    state.sessions = state.sessions.filter((s) => s.id !== id);
    if (isCurrent) {
      const next = state.sessions[Math.min(idx, state.sessions.length - 1)];
      state.renderedFor = null;
      if (next) return openChat(next.id).then(() => undoToast(copy));
      state.current = blank(); state.pending = true; render();
    }
    renderList(); undoToast(copy);
  } catch (err) { toast({ title: 'Delete failed', body: err.message, kind: 'danger' }); }
}

function undoToast(s) {
  toast({
    title: 'Session deleted',
    body: `${s.title} · ${s.messages.length} msg`,
    kind: 'danger',
    action: {
      label: 'Undo',
      run: async () => {
        try {
          await api('/api/sessions', { method: 'POST', body: JSON.stringify({ ...s, createdAt: s.createdAt }) });
          toast({ title: 'Restored', body: `${s.title}.json`, kind: 'ok', ms: 3200 });
          await refreshList();
        } catch (e) { toast({ title: 'Restore failed', body: e.message, kind: 'danger' }); }
      },
    },
  });
}

/* ══ sending ═════════════════════════════════════════════════════ */
async function send_() {
  const text = els.input.value.trim();
  if (!text || state.busy) return;
  if (!state.current) state.current = blank();
  const s = state.current;
  const ts = new Date().toISOString();
  s.messages.push({ id: uid('m'), role: 'user', content: text, ts });
  if (s.title === 'Untitled session') s.title = text.replace(/\s+/g, ' ').slice(0, 64);

  els.input.value = ''; autosize(); updateCount();
  state.busy = true; els.send.disabled = true;
  setStatus('saving', 'writing…');
  renderThread(); renderHead(); renderList();

  await saveNow().catch(() => {});

  // typing indicator
  const bubble = renderThread(true);
  try {
    const r = await api('/api/reply', { method: 'POST', body: JSON.stringify({ id: s.id, message: text }) });
    await typewrite(bubble, r.reply);
    s.messages.push({ id: uid('m'), role: 'assistant', content: r.reply, ts: r.ts || new Date().toISOString() });
  } catch (err) {
    s.messages.push({ id: uid('m'), role: 'assistant', content: `**Could not reach the model.** \`${err.message}\`\n\nYour message is safe — it is already in \`${state.file || s.id + '.json'}'. Fix the connection and resend.`, ts: new Date().toISOString() });
    toast({ title: 'Model error', body: err.message, kind: 'danger' });
  }
  state.busy = false; els.send.disabled = false;
  renderThread(); renderHead();
  await saveNow().catch(() => {});
  els.input.focus();
}

function typewrite(node, text) {
  if (!node) return Promise.resolve();
  return new Promise((done) => {
    let i = 0;
    const tick = () => {
      i = Math.min(text.length, i + Math.max(3, Math.round(text.length / 160)));
      node.innerHTML = md(text.slice(0, i));
      nearBottom() && scrollDown();
      if (i < text.length) requestAnimationFrame(tick); else done();
    };
    requestAnimationFrame(tick);
  });
}

/* ══ rendering ══════════════════════════════════════════════════ */
function render() { renderList(); renderHead(); renderThread(); renderPeek(true); }

function visible() {
  const q = state.query.trim().toLowerCase();
  let list = state.sessions.slice();
  if (q) list = list.filter((s) => s.title.toLowerCase().includes(q) || s.preview.toLowerCase().includes(q));
  if (state.sort === 'title') list.sort((a, b) => a.title.localeCompare(b.title));
  else if (state.sort === 'oldest') list.sort((a, b) => a.updatedAt.localeCompare(b.updatedAt));
  else list.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  return list;
}

function renderList() {
  const list = visible();
  els.filterCount.textContent = state.query ? `${list.length}/${state.sessions.length}` : '';
  const frag = document.createDocumentFragment();

  if (state.pending && state.current) frag.appendChild(row(state.current, true));
  list.forEach((s) => frag.appendChild(row(s, false)));
  els.sessions.replaceChildren(frag);
}

function row(s, isPending) {
  const cur = state.current && s.id === state.current.id;
  const li = document.createElement('li');
  li.className = `s${cur ? ' is-on' : ''}${isPending ? ' s--enter' : ''}`;
  li.dataset.id = s.id;
  const count = s.messageCount ?? s.messages?.length ?? 0;
  const bytes = s.bytes ?? 0;

  li.innerHTML = `
    <div class="s__body">
      <button class="s__main">
        <div class="s__top">
          <h3 class="s__title">${esc(cur && isPending && !count ? 'New session' : s.title)}</h3>
          <time class="s__time">${ago(s.updatedAt)}</time>
        </div>
        <p class="s__prev">${esc(s.preview || (s.messages?.[0]?.content || '').slice(0, 90) || 'No messages yet')}</p>
        <div class="s__meta">${count} msg<em>·</em>${isPending && !bytes ? 'unsaved' : human(bytes)}</div>
      </button>
      <div class="s__acts">
        <button data-act="rename" title="Rename"><svg viewBox="0 0 24 24"><path d="M4 20h4l10-10a2.8 2.8 0 0 0-4-4L4 16v4z" stroke="currentColor" stroke-width="1.9" fill="none" stroke-linejoin="round"/></svg></button>
        <button data-act="dl" title="Download .json"><svg viewBox="0 0 24 24"><path d="M12 4v11m0 0l-4-4m4 4l4-4M5 20h14" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" fill="none"/></svg></button>
        <button data-act="del" class="d" title="Delete"><svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4.6A.6.6 0 0 1 9.6 4h4.8a.6.6 0 0 1 .6.6V7M6 7l1 12.4A1.6 1.6 0 0 0 8.6 21h6.8A1.6 1.6 0 0 0 17 19.4L18 7" stroke="currentColor" stroke-width="1.9" fill="none" stroke-linecap="round"/></svg></button>
      </div>
    </div>
    <div class="s__confirm">Delete ${esc(s.title.slice(0, 18))}…?
      <button data-act="yes">Delete</button><button data-act="no" class="ghost">Keep</button>
    </div>`;

  li.querySelector('.s__main').onclick = () => openChat(s.id);
  li.querySelector('[data-act="dl"]').onclick = (e) => { e.stopPropagation(); window.location = `/api/sessions/${s.id}?download=1`; };
  li.querySelector('[data-act="rename"]').onclick = (e) => { e.stopPropagation(); startRename(li, s); };
  li.querySelector('[data-act="del"]').onclick = (e) => { e.stopPropagation(); li.classList.add('is-confirm'); setTimeout(() => li.classList.contains('is-confirm') && li.classList.remove('is-confirm'), 6000); };
  li.querySelector('[data-act="no"]').onclick = (e) => { e.stopPropagation(); li.classList.remove('is-confirm'); };
  li.querySelector('[data-act="yes"]').onclick = (e) => { e.stopPropagation(); removeChat(s.id); };
  li.querySelector('.s__main').ondblclick = (e) => { e.preventDefault(); startRename(li, s); };
  return li;
}

function startRename(li, s) {
  const h3 = li.querySelector('.s__title');
  const input = document.createElement('input');
  input.className = 'rename'; input.value = s.title;
  h3.replaceWith(input); input.focus(); input.select();
  const commit = async (save) => {
    if (!document.body.contains(input)) return;
    const v = input.value.trim();
    input.replaceWith(h3);
    if (!save || !v || v === s.title) { h3.textContent = s.title; return; }
    h3.textContent = v;
    if (state.current && state.current.id === s.id) { state.current.title = v; renderHead(); }
    try {
      await api(`/api/sessions/${s.id}?touch=0`, { method: 'PUT', body: JSON.stringify({ title: v }) });
      toast({ title: 'Renamed', body: `${s.id}.json`, kind: 'ok', ms: 2600 });
      await refreshList();
    } catch (e) { toast({ title: 'Rename failed', body: e.message, kind: 'danger' }); }
  };
  input.onkeydown = (e) => { if (e.key === 'Enter') commit(true); if (e.key === 'Escape') commit(false); };
  input.onblur = () => commit(true);
}

function renderHead() {
  const s = state.current;
  els.title.value = s ? s.title : 'Untitled session';
  if (!s) { els.headMeta.innerHTML = ''; return; }
  const count = s.messages.length;
  const w = s.messages.reduce((n, m) => n + words(m.content), 0);
  els.headMeta.innerHTML =
    `<span>${s.id}.json</span><span>created <b>${full(s.createdAt)}</b></span>` +
    `<span>updated <b>${ago(s.updatedAt)}</b></span><span><b>${count}</b> msg</span><span><b>${w}</b> words</span>` +
    `<span><b>${human(state.fileBytes)}</b> on disk</span>`;
}

function renderThread(indicator = false) {
  const s = state.current;
  if (!s || (!s.messages.length && !indicator)) { els.thread.replaceChildren(emptyState()); state.renderedFor = s ? s.id : null; return; }
  const stick = nearBottom();
  const frag = document.createDocumentFragment();
  s.messages.forEach((m) => frag.appendChild(msgNode(m)));
  let typingBubble = null;
  if (indicator) {
    const n = msgNode({ id: 'typing', role: 'assistant', content: '', ts: new Date().toISOString() });
    typingBubble = n.querySelector('.msg__body');
    typingBubble.innerHTML = '<span class="typing"><i></i><i></i><i></i></span>';
    frag.appendChild(n);
  }
  els.thread.replaceChildren(frag);
  state.renderedFor = s.id;
  if (stick) scrollDown();
  return typingBubble;
}

function msgNode(m) {
  const d = document.createElement('article');
  d.className = `msg msg--${m.role}`;
  d.innerHTML = `
    <div class="msg__av">${m.role === 'user' ? 'YOU' : 'LED'}</div>
    <div class="msg__col">
      <div class="msg__who"><b>${m.role === 'user' ? 'You' : 'Ledger'}</b><time>${ago(m.ts)}</time></div>
      <div class="msg__body">${md(m.content)}</div>
    </div>`;
  return d;
}

function emptyState() {
  const box = document.createElement('div');
  box.className = 'empty';
  const first = state.sessions.length === 0;
  box.innerHTML = `
    <div class="empty__kicker">${first ? 'store is empty' : 'no session open'}</div>
    <h2>${first ? 'Nothing<br>filed <span>yet.</span>' : 'Pick a file<br><span>or start one.</span>'}</h2>
    <p>${first
      ? 'Every message you send is written to data/sessions/&lt;id&gt;.json — an ordinary, greppable, backup-able file. No database between you and your history.'
      : 'The sidebar is a live index of the JSON files on disk. Click one to reopen it, or start a fresh conversation.'}</p>
    <div class="chips">
      ${first ? '' : '<button class="chip" data-q="">Back to the last thread</button>'}
      <button class="chip" data-q="How is this conversation stored on disk?">How is this stored on disk?</button>
      <button class="chip" data-q="Show me the atomic write code">Show me the atomic write code</button>
      <button class="chip" data-q="How do I delete a session?">How do I delete a session?</button>
    </div>`;
  box.querySelectorAll('.chip').forEach((c) => c.onclick = () => {
    if (!c.dataset.q) return;
    els.input.value = c.dataset.q; autosize(); updateCount(); els.input.focus();
  });
  return box;
}

/* ── json rail ──────────────────────────────────────────────────── */
function jsonHighlight(obj) {
  return esc(JSON.stringify(obj, null, 2))
    .replace(/^(\s*)&quot;([^&]*?)&quot;(\s*:)/gm, '$1<span class="jk">"$2"</span>$3')
    .replace(/:\s*&quot;([\s\S]*?)&quot(?=(,|\n)?$)/gm, ': <span class="js">"$1"</span>')
    .replace(/:\s*(-?\d+(?:\.\d+)?)(?=,|\n|$)/gm, ': <span class="jn">$1</span>')
    .replace(/:\s*(true|false|null)(?=,|\n|$)/gm, ': <span class="jb">$1</span>');
}

function renderPeek(flash = false) {
  const s = state.current;
  if (!s) { els.peekJson.textContent = ''; return; }
  const msgs = s.messages;
  const cut = (m) => ({ ...m, content: m.content.length > 118 ? m.content.slice(0, 118).replace(/\s+/g, ' ') + ' …' : m.content });
  let shown;
  if (msgs.length <= 3) shown = msgs.map(cut);
  else shown = [...msgs.slice(0, 2).map(cut), { id: '…', role: '…', content: `${msgs.length - 3} more message(s) on disk`, ts: null }, cut(msgs[msgs.length - 1])];

  els.peekJson.innerHTML = jsonHighlight({
    id: s.id, title: s.title, createdAt: s.createdAt, updatedAt: s.updatedAt,
    messageCount: msgs.length, path: state.file || `data/sessions/${s.id}.json` + (state.pending ? '  (not yet written)' : ''),
    messages: shown,
  });
  els.peekPath.textContent = state.file || `data/sessions/${s.id}.json`;
  els.peekStats.innerHTML = [
    ['bytes', state.pending ? '—' : human(state.fileBytes)],
    ['messages', msgs.length],
    ['words', msgs.reduce((n, m) => n + words(m.content), 0)],
    ['encoding', 'utf-8'],
    ['format', 'json · indent 2'],
    ['store size', `${state.stats.count} files · ${state.stats.readable}`],
  ].map(([k, v]) => `<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('');

  if (flash && state.fileBytes !== state.lastBytes) {
    els.peekJson.classList.remove('flash'); void els.peekJson.offsetWidth; els.peekJson.classList.add('flash');
  }
  state.lastBytes = state.fileBytes;
}

/* ── misc ui ────────────────────────────────────────────────────── */
const nearBottom = () => els.thread.scrollHeight - els.thread.scrollTop - els.thread.clientHeight < 140;
const scrollDown = () => (els.thread.scrollTop = els.thread.scrollHeight + 9999);
function autosize() { els.input.style.height = 'auto'; els.input.style.height = Math.min(196, els.input.scrollHeight) + 'px'; }
function updateCount() {
  const n = els.input.value.length;
  els.charCount.textContent = n ? String(n) : '0';
  els.charCount.style.color = n > 1600 ? 'var(--rose)' : '';
}

/* ══ wiring ═════════════════════════════════════════════════════ */
els.send.onclick = send_;
els.input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send_(); }
});
els.input.addEventListener('input', () => { autosize(); updateCount(); });

els.title.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); els.title.blur(); } });
els.title.addEventListener('blur', () => {
  const s = state.current; if (!s) return;
  const v = els.title.value.trim() || 'Untitled session';
  if (v === s.title) { els.title.value = s.title; return; }
  s.title = v; touch('renaming…');
});

$('newChat').onclick = () => newChat();
$('menuBtn').onclick = () => document.body.classList.toggle('rail-open');
$('scrim').onclick = () => document.body.classList.remove('rail-open');
$('peekBtn').onclick = (e) => {
  document.querySelector('.app').classList.toggle('peek-off');
  e.currentTarget.classList.toggle('is-on', !document.querySelector('.app').classList.contains('peek-off'));
};

let armed = false, armTimer;
$('deleteChat').onclick = async (e) => {
  const btn = e.currentTarget;
  if (!state.current) return;
  if (!armed) {
    armed = true; btn.classList.add('is-armed'); btn.innerHTML = 'Confirm delete';
    clearTimeout(armTimer); armTimer = setTimeout(() => { armed = false; btn.classList.remove('is-armed'); btn.innerHTML = '<svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4.6A.6.6 0 0 1 9.6 4h4.8a.6.6 0 0 1 .6.6V7M6 7l1 12.4A1.6 1.6 0 0 0 8.6 21h6.8A1.6 1.6 0 0 0 17 19.4L18 7" stroke="currentColor" stroke-width="1.9" fill="none" stroke-linecap="round"/></svg>'; }, 3500);
    return;
  }
  armed = false; btn.classList.remove('is-armed');
  btn.innerHTML = '<svg viewBox="0 0 24 24"><path d="M4 7h16M9 7V4.6A.6.6 0 0 1 9.6 4h4.8a.6.6 0 0 1 .6.6V7M6 7l1 12.4A1.6 1.6 0 0 0 8.6 21h6.8A1.6 1.6 0 0 0 17 19.4L18 7" stroke="currentColor" stroke-width="1.9" fill="none" stroke-linecap="round"/></svg>';
  removeChat(state.current.id);
};

els.search.addEventListener('input', () => { state.query = els.search.value; renderList(); });
els.sortbar.addEventListener('click', (e) => {
  const b = e.target.closest('button[data-sort]'); if (!b) return;
  state.sort = b.dataset.sort;
  [...els.sortbar.children].forEach((x) => x.classList.toggle('is-on', x === b));
  renderList();
});

$('clearAll').onclick = async (e) => {
  const b = e.currentTarget;
  if (b.dataset.armed) {
    b.dataset.armed = ''; b.textContent = 'Clear store';
    try { await api('/api/sessions', { method: 'DELETE' }); toast({ title: 'Store emptied', body: 'every .json in data/sessions is gone', kind: 'danger' }); state.current = blank(); state.pending = true; state.renderedFor = null; render(); }
    catch (err) { toast({ title: 'Failed', body: err.message, kind: 'danger' }); }
    return;
  }
  b.dataset.armed = '1'; b.textContent = `Delete ${state.stats.count} files?`;
  setTimeout(() => { if (b.dataset.armed) { b.dataset.armed = ''; b.textContent = 'Clear store'; } }, 4000);
};

els.thread.addEventListener('click', (e) => {
  const pre = e.target.closest('pre'); if (!pre) return;
  if (e.target.classList.contains('msg__copy')) {
    navigator.clipboard.writeText(pre.querySelector('code').textContent);
    e.target.textContent = 'copied'; setTimeout(() => (e.target.textContent = 'copy'), 1400);
    return;
  }
  if (!pre.querySelector('.msg__copy')) {
    const b = document.createElement('button'); b.className = 'msg__copy'; b.textContent = 'copy';
    pre.appendChild(b);
  }
});

document.addEventListener('keydown', (e) => {
  const mod = e.metaKey || e.ctrlKey;
  if (!mod) { if (e.key === 'Escape') document.body.classList.remove('rail-open'); return; }
  if (e.key.toLowerCase() === 'n') { e.preventDefault(); newChat(); }
  if (e.key.toLowerCase() === 'k') { e.preventDefault(); document.body.classList.add('rail-open'); els.search.focus(); els.search.select(); }
  if (e.key === 'Enter' && e.shiftKey) { e.preventDefault(); saveNow(); }
});

addEventListener('beforeunload', () => {
  const s = state.current;
  if (!s || state.pending) return;
  const blob = new Blob([JSON.stringify({ id: s.id, title: s.title, createdAt: s.createdAt, messages: s.messages })], { type: 'application/json' });
  navigator.sendBeacon(`/api/sessions/${s.id}`, blob);
});

/* clock refresh for relative times */
setInterval(() => { renderList(); }, 45000);

/* ══ boot ═══════════════════════════════════════════════════════ */
(async function boot() {
  $('peekBtn').classList.add('is-on');
  updateCount();
  try {
    await refreshList();
    const last = localStorage.getItem('ledger.current');
    const found = last && state.sessions.find((s) => s.id === last);
    if (found) await openChat(found.id);
    else { state.current = blank(); state.pending = true; setStatus('idle', 'not saved yet'); render(); }
  } catch (err) {
    setStatus('error', 'server offline');
    toast({ title: 'Cannot reach the store', body: `${err.message} — run \`npm start\``, kind: 'danger', ms: 12000 });
    state.current = blank(); state.pending = true; render();
  }
})();
